SELECT DATE_FORMAT(o.order_date, 'yyyy-MM') AS order_month, CASE WHEN o.channel IN ('store', 'web') THEN 'core' ELSE 'other' END AS channel_group, COUNT(*) AS total_count FROM order_items oi INNER JOIN products p ON oi.product_id = p.id INNER JOIN orders o ON oi.order_id = o.id GROUP BY DATE_FORMAT(o.order_date, 'yyyy-MM'), CASE WHEN o.channel IN ('store', 'web') THEN 'core' ELSE 'other' END ORDER BY channel_group, order_month LIMIT 5
